INSERT OR REPLACE INTO recipes (id, title, subtitle, emoji, category, tags, time_min, servings, difficulty, ingredients, steps, tips, missing, source_url, source, transcript, image, favorite, created, updated) VALUES ('792abdd09f', 'Спрэд из запечённых перцев', 'Простой соус-спрэд из печёных перцев', '🫑', 'Закуска', '[]', 30, 4, 'легко', '[{"name": "перец сладкий", "qty": "по вкусу", "est": "≈4 шт."}, {"name": "лук", "qty": "по вкусу", "est": "≈1 шт."}, {"name": "чеснок", "qty": "по вкусу", "est": "≈3 зубчика"}, {"name": "соль", "qty": "по вкусу", "est": "≈0,5 ч. л."}, {"name": "перец молотый", "qty": "по вкусу", "est": "≈щепотка"}, {"name": "сушёные травы (базилик)", "qty": "по вкусу", "est": "≈1 ч. л."}, {"name": "растительное масло", "qty": "по вкусу", "est": "≈3 ст. л."}]', '[{"n": 1, "text": "Перцы вымыть, разрезать пополам и удалить семена, перегородки и ножки.", "at": "0:08"}, {"n": 2, "text": "Половинки перцев отправить в аэрогриль.", "at": "0:12"}, {"n": 3, "text": "Лук нарезать крупно, чеснок разобрать зубчиками и добавить к перцам.", "at": "0:18"}, {"n": 4, "text": "Приправить солью, перцем и сушёными травами, влить растительное масло.", "at": "0:20"}, {"n": 5, "text": "Запекать 15–20 минут.", "at": "0:27"}, {"n": 6, "text": "Дать чуть остыть и пробить всё блендером до однородности.", "at": "0:30"}, {"n": 7, "text": "Переложить спрэд в банку и убрать в холодильник.", "at": "0:36"}]', '["Подавай спрэд на бутерброде или в сэндвиче, а также как соус к пасте.", "Особенно вкусно с поджаренным тостом."]', '["Не названы граммовки ингредиентов и температура запекания в аэрогриле.", "Не сказано, сколько спрэд хранится в холодильнике.", "Не уточнено, сколько именно порций получается из указанного набора продуктов."]', 'instagram:DeMc0k_Sc9-', '{"url": "https://www.instagram.com/reel/DeMc0k_Sc9-/?vrfl=MXcwZmlxanJydml2Ng==", "title": "Video by vsevsad", "author": "Sasha Demyanenko 🇨🇦🏳️‍🌈", "duration": 0, "thumbnail": "https://instagram.ftbs6-2.fna.fbcdn.net/v/t51.82787-15/839441193_18632658439053165_8683421474511309551_n.jpg?stp=dst-jpg_e15_tt6&_nc_cat=102&_nc_map=urlgen_bucketless&ig_cache_key=NDAwMjcwMDkyNzI1NzEzNzAyMjE4NjMyNjU4NDM2MDUzMTY1.3-ccb7-5&ccb=7-5&_nc_sid=58cdad&efg=eyJ2ZW5jb2RlX3RhZyI6IkNMSVBTLnhwaWRzLjg0NC5zZHIudmlkZW9fZGVmYXVsdF9jb3Zlcl9mcmFtZS5DMyJ9&_nc_ohc=oXPQ3OD0hFEQ7kNvwFrRYS5&_nc_oc=Adr3ZvkXs3gWVLoYx3tevP7pXB9R68t2VnwDWNkv8nPn5tdTLFCKm3iUWHp-E3UIv8I&_nc_zt=23&_nc_ht=instagram.ftbs6-2.fna&_nc_gid=NFF_aLQUvwuxlV6cBXhZRA&_nc_ss=78689&oh=00_AQQ3hMdreBcA5xLAGWaUQCUasThfFZgl_zA7y3JY_C8Dww&oe=6AE81DA7", "platform": "instagram"}', '', 'https://instagram.ftbs6-2.fna.fbcdn.net/v/t51.82787-15/839441193_18632658439053165_8683421474511309551_n.jpg?stp=dst-jpg_e15_tt6&_nc_cat=102&_nc_map=urlgen_bucketless&ig_cache_key=NDAwMjcwMDkyNzI1NzEzNzAyMjE4NjMyNjU4NDM2MDUzMTY1.3-ccb7-5&ccb=7-5&_nc_sid=58cdad&efg=eyJ2ZW5jb2RlX3RhZyI6IkNMSVBTLnhwaWRzLjg0NC5zZHIudmlkZW9fZGVmYXVsdF9jb3Zlcl9mcmFtZS5DMyJ9&_nc_ohc=oXPQ3OD0hFEQ7kNvwFrRYS5&_nc_oc=Adr3ZvkXs3gWVLoYx3tevP7pXB9R68t2VnwDWNkv8nPn5tdTLFCKm3iUWHp-E3UIv8I&_nc_zt=23&_nc_ht=instagram.ftbs6-2.fna&_nc_gid=NFF_aLQUvwuxlV6cBXhZRA&_nc_ss=78689&oh=00_AQQ3hMdreBcA5xLAGWaUQCUasThfFZgl_zA7y3JY_C8Dww&oe=6AE81DA7', 0, 1793257825.178787, 1793257825.178787);
INSERT OR REPLACE INTO recipes (id, title, subtitle, emoji, category, tags, time_min, servings, difficulty, ingredients, steps, tips, missing, source_url, source, transcript, image, favorite, created, updated) VALUES ('db542d00e4', 'Идеальные тонкие блинчики на молоке', 'Универсальные: держат форму, годятся для начинки', '🥞', 'Завтрак', '[]', 40, 4, 'легко', '[{"name": "яйца крупные", "qty": "2 шт.", "est": "≈2 шт. (≈110 г)"}, {"name": "соль", "qty": "1/3 ч.л.", "est": "≈1/3 ч.л."}, {"name": "сахар", "qty": "2 ст.л. с горкой", "est": "≈2 ст.л. (≈50 г)"}, {"name": "ванильный сахар", "qty": "1 ч.л.", "est": "≈1 ч.л. (≈5 г)"}, {"name": "растительное масло", "qty": "3 ст.л.", "est": "≈3 ст.л. (≈45 мл)"}, {"name": "мука", "qty": "150 г", "est": "≈150 г"}, {"name": "молоко (тёплое или комнатной температуры)", "qty": "500 г", "est": "≈500 мл"}, {"name": "растительное масло для смазывания сковороды", "qty": "по вкусу", "est": "≈1 ст.л."}]', '[{"n": 1, "text": "В миску разбить яйца, добавить соль, сахар, ванильный сахар и растительное масло.", "at": "0:25"}, {"n": 2, "text": "Перемешать венчиком, затем добавить муку и перемешать её вместе с яйцами и сахаром до густой однородной массы.", "at": "0:51"}, {"n": 3, "text": "Порциями добавлять молоко, вмешивая его постепенно, пока не уйдёт всё молоко.", "at": "1:06"}, {"n": 4, "text": "Оставить тесто при комнатной температуре на 15–20 минут, чтобы набухла клейковина муки.", "at": "1:47"}, {"n": 5, "text": "Хорошо разогреть сковороду и перед первым блинчиком слегка смазать её растительным маслом.", "at": "1:57"}, {"n": 6, "text": "Перед каждым блинчиком перемешать тесто, набрать немного и распределить по всей сковороде (диаметр 26 см).", "at": "2:09"}, {"n": 7, "text": "Выпекать на достаточно сильном огне, не отходя, пока края не начнут румяниться и верх не схватится, затем перевернуть и допечь ещё пару секунд.", "at": "2:23"}, {"n": 8, "text": "Складывать блинчики стопкой на тарелку; чтобы они стали мягкими, накрыть крышкой и дать пропариться 5 минут.", "at": "2:57"}]', '["Если яйца мелкие, возьмите 3 штуки вместо 2 крупных.", "Для более сладких блинчиков можно положить 3 столовые ложки сахара, а количество сахара вообще регулируйте по вкусу.", "Молоко лучше брать не из холодильника — комнатной температуры или слегка подогретое.", "Муку добавляйте до молока — так тесто всегда получается без комочков, даже если мешать просто вилкой.", "Накрытые крышкой блинчики становятся пластичными и не рвутся при заворачивании любой начинки."]', '["Точный объём соли и масла для смазывания сковороды автор не назвал (соль указана неоднозначно).", "Не сказано, сколько теста наливать на один блин — половником или мерным стаканом.", "Нет рекомендаций, как хранить и разогревать готовые блинчики."]', 'youtube:b5q5n1wUE18', '{"url": "https://www.youtube.com/watch?v=b5q5n1wUE18", "title": "Идеальные блинчики, которые получаются всегда! Тонкие блинчики на молоке!", "author": "FooDee", "duration": 273, "thumbnail": "https://i.ytimg.com/vi/b5q5n1wUE18/maxresdefault.jpg", "platform": "youtube"}', '', 'https://i.ytimg.com/vi/b5q5n1wUE18/maxresdefault.jpg', 0, 1793257825.179819, 1793257825.179819);
INSERT OR REPLACE INTO recipes (id, title, subtitle, emoji, category, tags, time_min, servings, difficulty, ingredients, steps, tips, missing, source_url, source, transcript, image, favorite, created, updated) VALUES ('ddcdb6e5da', 'Паста Карбонара со сливками и беконом', 'Спагетти в сливочном соусе с беконом и пармезаном', '🍝', 'Основное', '["паста"]', 30, 2, 'легко', '[{"name": "спагетти из твёрдых сортов пшеницы", "qty": "по вкусу", "est": "≈200 г"}, {"name": "соль", "qty": "по вкусу", "est": "≈½ ч. л."}, {"name": "яичные желтки", "qty": "по вкусу", "est": "≈2 шт."}, {"name": "сливки", "qty": "по вкусу", "est": "≈150 мл"}, {"name": "тёртый пармезан (или другой твёрдый сыр)", "qty": "по вкусу", "est": "≈50 г"}, {"name": "свежемолотый перец", "qty": "по вкусу", "est": "≈щепотка"}, {"name": "бекон", "qty": "по вкусу", "est": "≈150 г"}, {"name": "чеснок", "qty": "по вкусу", "est": "≈2 зубчика"}, {"name": "петрушка", "qty": "по вкусу", "est": "≈10 г"}]', '[{"n": 1, "text": "В большой кастрюле довести до кипения большое количество воды, добавить соль и положить спагетти.", "at": "0:27"}, {"n": 2, "text": "Варить спагетти до состояния аль денте — примерно на одну минуту меньше, чем указано на упаковке.", "at": "0:42"}, {"n": 3, "text": "В миску положить яичные желтки, добавить сливки и хорошо перемешать.", "at": "0:50"}, {"n": 4, "text": "Добавить тёртый пармезан, совсем немножко соли и свежемолотый перец, перемешать соус и отставить в сторону.", "at": "0:54"}, {"n": 5, "text": "Бекон нарезать соломкой.", "at": "1:13"}, {"n": 6, "text": "Разогреть сковороду, выложить бекон и жарить на среднем огне около двух минут до вытапливания жира, не пережаривая — бекон должен оставаться мягким.", "at": "1:23"}, {"n": 7, "text": "Добавить рубленый чеснок и рубленую петрушку, всё перемешать и выключить огонь.", "at": "1:43"}, {"n": 8, "text": "Готовые спагетти откинуть на дуршлаг и дать жидкости хорошо стечь.", "at": "2:08"}, {"n": 9, "text": "Соединить спагетти с обжаренным беконом, петрушкой и чесноком и хорошо перемешать.", "at": "2:14"}, {"n": 10, "text": "Добавить к горячим спагетти сливочный соус и ещё раз всё хорошенько перемешать — от горячей пасты и бекона желтки быстро дойдут до готовности.", "at": "2:22"}, {"n": 11, "text": "Сразу подать пасту к столу, щедро посыпав свежемолотым перцем и тёртым пармезаном.", "at": "2:32"}]', '["Берите спагетти из твёрдых сортов пшеницы — они вкуснее и полезнее.", "Варите пасту на минуту меньше указанного на упаковке времени, чтобы она осталась упругой.", "Бекон не пережаривайте: он должен оставаться мягким."]', '["Не названа ни одна точная граммовка ингредиентов — все количества определяются на глаз.", "Не указано, на сколько порций рассчитан рецепт.", "Не сказано точное время варки спагетти в минутах — только «на минуту меньше, чем на упаковке»."]', 'youtube:jVNX5aIo-IA', '{"url": "https://www.youtube.com/watch?v=jVNX5aIo-IA", "title": "Паста КАРБОНАРА. Спагетти Карбонара со сливками и беконом. Готовим дома", "author": "Cooking at Home", "duration": 178, "thumbnail": "https://i.ytimg.com/vi_webp/jVNX5aIo-IA/maxresdefault.webp", "platform": "youtube"}', '', 'https://i.ytimg.com/vi_webp/jVNX5aIo-IA/maxresdefault.webp', 0, 1793257825.180821, 1793257825.180821);
INSERT OR REPLACE INTO recipes (id, title, subtitle, emoji, category, tags, time_min, servings, difficulty, ingredients, steps, tips, missing, source_url, source, transcript, image, favorite, created, updated) VALUES ('demo000001', 'Паста карбонара', 'Классика без сливок: эмульсия из желтка и сыра', '🍝', 'Основное', '["паста"]', 25, 2, 'средне', '[{"name": "спагетти", "qty": "по вкусу", "est": "≈200 г"}, {"name": "оливковое масло", "qty": "по вкусу", "est": "≈2 ст. л."}, {"name": "соль", "qty": "по вкусу", "est": "≈1 ч. л."}, {"name": "копчёная свиная грудинка", "qty": "по вкусу", "est": "≈150 г"}, {"name": "чёрный перец", "qty": "по вкусу", "est": "≈1 ч. л."}, {"name": "петрушка", "qty": "по вкусу", "est": "≈20 г"}, {"name": "яичный желток", "qty": "по вкусу", "est": "≈2 шт."}, {"name": "сыр пармезан", "qty": "по вкусу", "est": "≈50 г"}, {"name": "вода от варки пасты", "qty": "по вкусу", "est": "≈50 мл"}]', '[{"n": 1, "text": "Ставим воду на огонь, добавляем оливковое масло и соль и отвариваем спагетти до готовности.", "at": "1:16"}, {"n": 2, "text": "Сковороду сразу ставим на огонь и хорошо разогреваем.", "at": "1:25"}, {"n": 3, "text": "Копчёную грудинку нарезаем кубиком и обжариваем до состояния шкварок.", "at": "1:34"}, {"n": 4, "text": "Петрушку мелко рубим.", "at": "2:00"}, {"n": 5, "text": "К обжаривающейся грудинке добавляем чёрный перец и продолжаем жарить.", "at": "2:16"}, {"n": 6, "text": "В яичный желток добавляем пармезан и очень хорошо размешиваем.", "at": "2:47"}, {"n": 7, "text": "Вливаем небольшое количество воды, в которой варится паста, и размешиваем до состояния эмульсии.", "at": "2:55"}, {"n": 8, "text": "В эмульсию добавляем рубленую петрушку.", "at": "3:14"}, {"n": 9, "text": "Готовую пасту откидываем, не обдавая водой, и сбрызгиваем оливковым маслом, чтобы она не слиплась.", "at": "3:20"}, {"n": 10, "text": "Выкладываем пасту на сковороду к шкваркам из грудинки.", "at": "3:37"}, {"n": 11, "text": "Выливаем яичную массу и всю эту историю начинаем тщательно замешивать и перемешивать.", "at": "3:45"}, {"n": 12, "text": "Пробуем и при необходимости добавляем соль.", "at": "3:55"}, {"n": 13, "text": "Выкладываем на самую красивую тарелку и подаём.", "at": "4:05"}]', '["Сливки не используем — их заменяет эмульсия из желтка, пармезана и воды от варки пасты.", "Грудинка должна быть прямо в перце, но не суйте сразу нос в сковороду.", "Самое важное — не дать желтку свариться: должна получиться гладкая эмульсия.", "Готовую пасту не обдавайте водой, иначе соус хуже ляжет."]', '["Не названа точная граммовка ни одного ингредиента — только «небольшое количество».", "Не указано время варки пасты и общее время приготовления.", "Не сказано, на сколько порций рассчитан рецепт."]', 'youtube:Uc_jAgchmXY', '{"url": "https://www.youtube.com/watch?v=Uc_jAgchmXY", "title": "ПАСТА КАРБОНАРА ОТ ШЕФА ИВЛЕВА", "author": "IVLEV CHEF", "duration": 314, "thumbnail": "https://i.ytimg.com/vi_webp/Uc_jAgchmXY/maxresdefault.webp", "platform": "youtube"}', '', 'https://i.ytimg.com/vi_webp/Uc_jAgchmXY/maxresdefault.webp', 0, 1793257825.1817632, 1793257825.1817632);
INSERT OR REPLACE INTO recipes (id, title, subtitle, emoji, category, tags, time_min, servings, difficulty, ingredients, steps, tips, missing, source_url, source, transcript, image, favorite, created, updated) VALUES ('e52687e833', 'Пышный омлет с помидорами и сыром', 'Воздушный омлет с творожным сыром и черри за 10 минут', '🍳', 'Завтрак', '[]', 10, 2, 'легко', '[{"name": "куриные яйца", "qty": "4 шт", "est": "4 шт"}, {"name": "помидоры черри", "qty": "50 г", "est": "≈50 г (5–6 шт)"}, {"name": "сыр творожный", "qty": "50 г", "est": "≈50 г (2 ст.л.)"}, {"name": "молоко", "qty": "2 ст.л.", "est": "≈30 мл"}, {"name": "сливочное масло", "qty": "20 г", "est": "≈20 г"}, {"name": "свежая петрушка", "qty": "5 г", "est": "≈5 г (небольшой пучок)"}, {"name": "перец черный молотый", "qty": "по вкусу", "est": "≈1 щепотка"}, {"name": "соль", "qty": "по вкусу", "est": "≈1 щепотка"}]', '[{"n": 1, "text": "Помидоры черри нарезать дольками, свежую петрушку мелко нарезать.", "at": ""}, {"n": 2, "text": "В миске взбить венчиком или вилкой куриные яйца с солью, перцем и молоком до однородности.", "at": ""}, {"n": 3, "text": "Нагреть сковороду на среднем огне, добавить сливочное масло и петрушку, обжарить 1 минуту.", "at": ""}, {"n": 4, "text": "Влить взбитые яйца в сковороду и готовить на среднем огне.", "at": ""}, {"n": 5, "text": "Через 20 секунд, когда омлет начнет схватываться и появятся пузырьки, убавить огонь до минимального и лопаткой по кругу собрать омлет от края к середине, чтобы яйца стекали по краям.", "at": ""}, {"n": 6, "text": "На одну половину омлета выложить начинку: творожный сыр и помидоры черри.", "at": ""}, {"n": 7, "text": "Лопаткой аккуратно сложить омлет вдвое, завернув вторую половину.", "at": ""}, {"n": 8, "text": "Готовить омлет еще 1 минуту на слабом огне.", "at": ""}, {"n": 9, "text": "Перевернуть омлет на тарелку.", "at": ""}, {"n": 10, "text": "Подавать омлет горячим, при желании с листьями салата и свежими или маринованными огурцами, дополнив тостами или хлебцами.", "at": ""}]', '["Начинка для омлета может быть разной по вашему вкусу.", "Сливочное масло можно заменить на растительное.", "Омлет можно оставить открытым, не складывая пополам.", "Сыр можно использовать любой, на ваш выбор."]', '["В видео не названо, на сколько именно порций рассчитаны граммовки (в описании указано 2 порции).", "Не уточнено, какой именно творожный сыр брать — классический, сливочный или с добавками.", "Нет таймкодов и не сказано, как долго держать омлет на огне до полной готовности после складывания, кроме «еще 1 минуты»."]', 'youtube:VaMpLoUjCEI', '{"url": "https://www.youtube.com/watch?v=VaMpLoUjCEI", "title": "Вкусный завтрак за 10 минут! Пышный ОМЛЕТ С ПОМИДОРАМИ И СЫРОМ на сковороде! Рецепт от Всегда Вкусно", "author": "Всегда Вкусно!", "duration": 98, "thumbnail": "https://i.ytimg.com/vi/VaMpLoUjCEI/maxresdefault.jpg", "platform": "youtube"}', '', 'https://i.ytimg.com/vi/VaMpLoUjCEI/maxresdefault.jpg', 0, 1793257825.184586, 1793257825.184586);
INSERT OR REPLACE INTO recipes (id, title, subtitle, emoji, category, tags, time_min, servings, difficulty, ingredients, steps, tips, missing, source_url, source, transcript, image, favorite, created, updated) VALUES ('ca92dc1a43', 'Гречневая каша с овощами', 'Гречка с кабачками, морковью и луком на одной сковороде', '🍲', '', '[]', 40, 5, 'легко', '[{"name": "гречневая крупа", "qty": "230 г", "est": "≈230 г"}, {"name": "кабачки свежие", "qty": "420 г", "est": "≈420 г"}, {"name": "морковь", "qty": "120 г", "est": "≈120 г"}, {"name": "лук репчатый", "qty": "100 г", "est": "≈100 г"}, {"name": "масло сливочное", "qty": "50 г", "est": "≈50 г"}, {"name": "зелёный лук", "qty": "10 г", "est": "≈10 г"}, {"name": "растительное масло", "qty": "2 ст.л.", "est": "≈2 ст.л."}, {"name": "вода", "qty": "400 мл", "est": "≈400 мл"}, {"name": "соль", "qty": "1 ч.л.", "est": "≈1 ч.л."}]', '[{"n": 1, "text": "Кабачки и морковь нарезать небольшими дольками.", "at": ""}, {"n": 2, "text": "Репчатый лук измельчить.", "at": ""}, {"n": 3, "text": "Гречневую крупу промыть.", "at": ""}, {"n": 4, "text": "Разогреть сковороду на среднем огне, добавить 2 ст.л. растительного масла и репчатый лук.", "at": ""}, {"n": 5, "text": "Обжарить лук на среднем огне 3 минуты.", "at": ""}, {"n": 6, "text": "Добавить в сковороду гречневую крупу и обжаривать на среднем огне ещё 2–3 минуты.", "at": ""}, {"n": 7, "text": "Добавить морковь, кабачки, сливочное масло, соль и воду, перемешать и довести до кипения.", "at": ""}, {"n": 8, "text": "Закрыть крышкой, убавить огонь до слабого и варить кашу 30 минут, пока вся жидкость не впитается.", "at": ""}, {"n": 9, "text": "Перед подачей посыпать кашу мелко нарезанным зелёным луком.", "at": ""}]', '["Вся жидкость должна впитаться — это главный признак готовности каши.", "Блюдо подойдёт на завтрак, обед или ужин, а также как гарнир к мясу или рыбе."]', '["Не уточнено, нужно ли перемешивать кашу во время 30-минутной варки.", "Не сказано, какой сорт гречки нужен — ядрица или продел.", "Нет таймкодов и не показано, как проверить готовность каши помимо испарения жидкости."]', 'youtube:1WzcpJPF_YY', '{"url": "https://www.youtube.com/watch?v=1WzcpJPF_YY", "title": "Вкусно, просто и полезно! ГРЕЧНЕВАЯ КАША С ОВОЩАМИ. Рецепт от Всегда Вкусно!", "author": "Всегда Вкусно!", "duration": 142, "thumbnail": "https://i.ytimg.com/vi_webp/1WzcpJPF_YY/maxresdefault.webp", "platform": "youtube"}', '', '', 0, 1793258452.312018, 1793258452.312018);
INSERT OR REPLACE INTO recipes (id, title, subtitle, emoji, category, tags, time_min, servings, difficulty, ingredients, steps, tips, missing, source_url, source, transcript, image, favorite, created, updated) VALUES ('4aeadd5024', 'Куриные котлеты с луком и хлебом в молоке', 'Сочные котлеты из куриного фарша по двум секретам', '🍗', 'Основное', '[]', 30, 2, 'легко', '[{"name": "куриный фарш", "qty": "по вкусу", "est": "≈500 г"}, {"name": "лук", "qty": "по вкусу", "est": "≈1 средняя луковица"}, {"name": "сливочное масло", "qty": "по вкусу", "est": "≈30 г"}, {"name": "хлеб", "qty": "по вкусу", "est": "≈2 ломтика"}, {"name": "молоко", "qty": "по вкусу", "est": "≈100 мл"}, {"name": "соль", "qty": "по вкусу", "est": "≈½ ч. л."}, {"name": "перец", "qty": "по вкусу", "est": "≈¼ ч. л."}, {"name": "мука", "qty": "по вкусу", "est": "≈3 ст. л. для панировки"}]', '[{"n": 1, "text": "Обжарить лук на сливочном масле — это первый секрет сочности котлет.", "at": "0:03"}, {"n": 2, "text": "Замочить хлеб в молоке — так котлеты получатся мягкими и воздушными.", "at": "0:08"}, {"n": 3, "text": "Смешать куриный фарш, обжаренный лук, соль, перец и вымоченный хлеб.", "at": "0:13"}, {"n": 4, "text": "Мокрыми руками сформировать котлеты и обвалять их в муке.", "at": "0:16"}, {"n": 5, "text": "Обжарить котлеты по 4 минуты с каждой стороны.", "at": "0:20"}]', '["Обжаренный на сливочном масле лук делает котлеты нереально сочными.", "Хлеб, вымоченный в молоке, помогает сделать котлеты мягкими и воздушными.", "Формируйте котлеты мокрыми руками — так фарш не липнет и форма выходит идеальной."]', '["Точные граммовки всех ингредиентов — автор говорит, что оставила пропорции в описании, но в видео их не называет.", "Количество порций и общее время приготовления.", "Точные параметры жарки: огонь, вид сковороды и количество масла."]', 'instagram:DNOFnf2M2CW', '{"url": "https://www.instagram.com/reel/DNOFnf2M2CW/?mdxt=MXhrcGQxYWwzeGVzcA==", "title": "Video by natali_barakos", "author": "Натали •блогер & influencer", "duration": 0, "thumbnail": "https://instagram.ftbs6-2.fna.fbcdn.net/v/t51.82787-15/530853268_18517664698031291_6215447992417748722_n.jpg?stp=dst-jpg_e15_tt6&_nc_cat=107&_nc_map=urlgen_bucketless&ig_cache_key=MzY5NjkxNzA0ODYwNTIzNzM5ODE4NTE3NjY0NjkyMDMxMjkx.3-ccb7-5&ccb=7-5&_nc_sid=58cdad&efg=eyJ2ZW5jb2RlX3RhZyI6IkNMSVBTLnhwaWRzLjEyMzAuc2RyLnZpZGVvX2RlZmF1bHRfY292ZXJfZnJhbWUuQzMifQ%3D%3D&_nc_ohc=DQdmV4rBeEAQ7kNvwH4sZPk&_nc_oc=Adqqj1uDF4kyqJZ02gJ2zKR5WJDX0CbUo9PvV8cqzBJa6xMbMGsXEQMrRjLl-obF2W8&_nc_zt=23&_nc_ht=instagram.ftbs6-2.fna&_nc_gid=2EAAY9JVzJQJYYG4bCcAJQ&_nc_ss=78689&oh=00_AQTzEdgtzA7MBWz6xQUDsSOBlvSKREmwdf8MOfA_iYXfGg&oe=6AE82A10", "platform": "instagram"}', '', 'https://instagram.ftbs6-2.fna.fbcdn.net/v/t51.82787-15/530853268_18517664698031291_6215447992417748722_n.jpg?stp=dst-jpg_e15_tt6&_nc_cat=107&_nc_map=urlgen_bucketless&ig_cache_key=MzY5NjkxNzA0ODYwNTIzNzM5ODE4NTE3NjY0NjkyMDMxMjkx.3-ccb7-5&ccb=7-5&_nc_sid=58cdad&efg=eyJ2ZW5jb2RlX3RhZyI6IkNMSVBTLnhwaWRzLjEyMzAuc2RyLnZpZGVvX2RlZmF1bHRfY292ZXJfZnJhbWUuQzMifQ%3D%3D&_nc_ohc=DQdmV4rBeEAQ7kNvwH4sZPk&_nc_oc=Adqqj1uDF4kyqJZ02gJ2zKR5WJDX0CbUo9PvV8cqzBJa6xMbMGsXEQMrRjLl-obF2W8&_nc_zt=23&_nc_ht=instagram.ftbs6-2.fna&_nc_gid=2EAAY9JVzJQJYYG4bCcAJQ&_nc_ss=78689&oh=00_AQTzEdgtzA7MBWz6xQUDsSOBlvSKREmwdf8MOfA_iYXfGg&oe=6AE82A10', 0, 1793257825.177616, 1793261963.560631);
